source='''def transform(grid):
    grid = [list(row) for row in grid]
    base = grid[0][0]
    frame_width = 0
    for value in grid[0]:
        if value != base:
            break
        frame_width += 1

    separators = [r for r, row in enumerate(grid) if all(v == base for v in row[:frame_width])]
    bands = [(a + 1, b) for a, b in zip(separators, separators[1:]) if b > a + 1]

    objects = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row[frame_width:], start=frame_width):
            if value != 0:
                objects.setdefault(value, []).append((r, c))
    shapes = {}
    for color, points in objects.items():
        point_set = set(points)
        min_r = min(r for r, c in points)
        max_r = max(r for r, c in points)
        min_c = min(c for r, c in points)
        max_c = max(c for r, c in points)
        shapes[color] = [[(r, c) in point_set for c in range(min_c, max_c + 1)]
                         for r in range(min_r, max_r + 1)]

    result = [row[:frame_width] for row in grid]
    for start, end in bands:
        target = [[grid[r][c] == 0 for c in range(1, frame_width - 1)] for r in range(start, end)]
        for color, shape in shapes.items():
            h, w = len(target), len(target[0])
            sh, sw = len(shape), len(shape[0])
            if sh > h or sw > w:
                continue
            padded = [[False] * w for _ in range(h)]
            top, left = (h - sh) // 2, (w - sw) // 2
            for r in range(sh):
                for c in range(sw):
                    padded[top + r][left + c] = shape[r][c]
            if target == padded:
                for r in range(start, end):
                    for c in range(1, frame_width - 1):
                        if result[r][c] == 0:
                            result[r][c] = color
                break
    return result
'''
